-- 4. Questions (Topic 57: History & Bitcoin Basics - 13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000901', '50000000-0000-0000-0000-000000000057', 'simple', 'mcq', 'Who is the pseudonymous creator of Bitcoin?', '["Vitalik Buterin", "Satoshi Nakamoto", "Charlie Lee", "Hal Finney"]', 'Satoshi Nakamoto', 'Satoshi Nakamoto published the Bitcoin whitepaper in 2008.', 'active'),
('60000000-0000-0000-0000-000000000902', '50000000-0000-0000-0000-000000000057', 'simple', 'mcq', 'What is a "Blockchain"?', '["A type of physical chain", "A distributed digital ledger that records transactions across many computers", "A database owned by a bank", "A social media platform"]', 'A distributed digital ledger that records transactions across many computers', 'Blockchains are characterized by their decentralization and immutability.', 'active'),
('60000000-0000-0000-0000-000000000903', '50000000-0000-0000-0000-000000000057', 'simple', 'mcq', 'What is the maximum supply of Bitcoin?', '["10 Million", "21 Million", "100 Million", "Unlimited"]', '21 Million', 'Bitcoin has a hard-capped supply of 21 million BTC.', 'active'),
('60000000-0000-0000-0000-000000000904', '50000000-0000-0000-0000-000000000057', 'simple', 'mcq', 'What is a "Genesis Block"?', '["The last block in a chain", "The first block of a blockchain", "A block containing only fees", "A corrupted block"]', 'The first block of a blockchain', 'The Bitcoin genesis block was mined by Satoshi Nakamoto on January 3, 2009.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000905', '50000000-0000-0000-0000-000000000057', 'intermediate', 'mcq', 'What is "Mining" in Bitcoin?', '["Digging for gold", "The process of verifying transactions and adding them to the public ledger", "Buying Bitcoin on an exchange", "Deleting old transactions"]', 'The process of verifying transactions and adding them to the public ledger', 'Miners use computational power to solve complex mathematical puzzles.', 'active'),
('60000000-0000-0000-0000-000000000906', '50000000-0000-0000-0000-000000000057', 'intermediate', 'mcq', 'What is a "Wallet Address" in crypto?', '["A physical folder", "A string of alphanumeric characters that represents a destination for a cryptocurrency payment", "A login password", "A bank account number"]', 'A string of alphanumeric characters that represents a destination for a cryptocurrency payment', 'Wallet addresses are derived from public keys.', 'active'),
('60000000-0000-0000-0000-000000000907', '50000000-0000-0000-0000-000000000057', 'intermediate', 'mcq', 'What is a "Cold Wallet"?', '["A wallet kept in a freezer", "A cryptocurrency wallet that is not connected to the internet", "A wallet with no money", "A type of mobile app"]', 'A cryptocurrency wallet that is not connected to the internet', 'Cold wallets provide high security against online hacking attempts.', 'active'),
('60000000-0000-0000-0000-000000000908', '50000000-0000-0000-0000-000000000057', 'intermediate', 'mcq', 'What is "Halving" in Bitcoin?', '["Cutting a physical coin", "An event where the reward for mining new blocks is cut in half", "Selling half of your stash", "A type of fork"]', 'An event where the reward for mining new blocks is cut in half', 'Bitcoin halving occurs approximately every four years.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000909', '50000000-0000-0000-0000-000000000057', 'expert', 'mcq', 'Explain "UTXO" (Unspent Transaction Output) model.', '["A way to delete transactions", "A model where the balance is the sum of unspent outputs from previous transactions", "A type of smart contract", "A database index"]', 'A model where the balance is the sum of unspent outputs from previous transactions', 'Bitcoin uses the UTXO model, unlike Ethereum which uses an account-based model.', 'active'),
('60000000-0000-0000-0000-000000000910', '50000000-0000-0000-0000-000000000057', 'expert', 'mcq', 'What is the "Double Spending" problem?', '["Spending twice as much money", "The risk that a digital currency can be spent more than once", "A type of inflation", "Buying two coffees"]', 'The risk that a digital currency can be spent more than once', 'Blockchain solves double spending through consensus and timestamping.', 'active'),
('60000000-0000-0000-0000-000000000911', '50000000-0000-0000-0000-000000000057', 'expert', 'mcq', 'What is "SegWit" (Segregated Witness)?', '["A type of witness", "An upgrade to Bitcoin that increases block size limit by removing signature data from transactions", "A type of wallet", "A network fork"]', 'An upgrade to Bitcoin that increases block size limit by removing signature data from transactions', 'SegWit improves scalability and fixes transaction malleability.', 'active'),
('60000000-0000-0000-0000-000000000912', '50000000-0000-0000-0000-000000000057', 'expert', 'mcq', 'What is the "Lightning Network"?', '["A weather app", "A layer 2 payment protocol that operates on top of Bitcoin to enable fast, low-fee transactions", "A type of mining hardware", "A fast database"]', 'A layer 2 payment protocol that operates on top of Bitcoin to enable fast, low-fee transactions', 'Lightning network uses payment channels between participants.', 'active'),
('60000000-0000-0000-0000-000000000913', '50000000-0000-0000-0000-000000000057', 'expert', 'mcq', 'Explain "Merkle Trees" in blockchain.', '["A type of forest", "A mathematical way to verify the integrity of data in a block efficiently", "A type of consensus", "A UI component"]', 'A mathematical way to verify the integrity of data in a block efficiently', 'Merkle trees allow for quick verification that a transaction is included in a block.', 'active');

-- Topic 58: Consensus Mechanisms (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000914', '50000000-0000-0000-0000-000000000058', 'simple', 'mcq', 'What is "Consensus" in blockchain?', '["Everyone having a different opinion", "Agreement among nodes on the state of the ledger", "A vote for a president", "A type of database query"]', 'Agreement among nodes on the state of the ledger', 'Consensus is the core mechanism that keeps a decentralized network in sync.', 'active'),
('60000000-0000-0000-0000-000000000915', '50000000-0000-0000-0000-000000000058', 'simple', 'mcq', 'What does "PoW" stand for?', '["Piece of Work", "Proof of Work", "Power of Web", "Point of Weight"]', 'Proof of Work', 'PoW involves solving computational puzzles to validate transactions.', 'active'),
('60000000-0000-0000-0000-000000000916', '50000000-0000-0000-0000-000000000058', 'simple', 'mcq', 'What does "PoS" stand for?', '["Piece of Stake", "Proof of Stake", "Point of Sale", "Power of Security"]', 'Proof of Stake', 'PoS selects validators based on the number of coins they hold and are willing to "stake".', 'active'),
('60000000-0000-0000-0000-000000000917', '50000000-0000-0000-0000-000000000058', 'simple', 'mcq', 'Which consensus mechanism is used by Bitcoin?', '["PoS", "PoW", "DPoS", "pBFT"]', 'PoW', 'Bitcoin remains the most prominent blockchain using Proof of Work.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000918', '50000000-0000-0000-0000-000000000058', 'intermediate', 'mcq', 'What is a "Fork" in blockchain?', '["A tool for eating", "A split in the blockchain network resulting in two different paths", "A type of consensus", "A security leak"]', 'A split in the blockchain network resulting in two different paths', 'Forks can be "soft" (backward-compatible) or "hard" (incompatible).', 'active'),
('60000000-0000-0000-0000-000000000919', '50000000-0000-0000-0000-000000000058', 'intermediate', 'mcq', 'What is "Slashing" in Proof of Stake?', '["Cutting a price", "A penalty mechanism where a validator loses part of their staked assets for malicious behavior", "Buying more coins", "A type of UI animation"]', 'A penalty mechanism where a validator loses part of their staked assets for malicious behavior', 'Slashing incentivizes validators to follow the network rules.', 'active'),
('60000000-0000-0000-0000-000000000920', '50000000-0000-0000-0000-000000000058', 'intermediate', 'mcq', 'What is "DPoS" (Delegated Proof of Stake)?', '["Giving coins away", "A consensus mechanism where stakeholders elect delegates to validate blocks", "A type of database", "A network router"]', 'A consensus mechanism where stakeholders elect delegates to validate blocks', 'DPoS is often faster and more efficient than traditional PoS.', 'active'),
('60000000-0000-0000-0000-000000000921', '50000000-0000-0000-0000-000000000058', 'intermediate', 'mcq', 'What is the "Byzantine Generals Problem"?', '["A strategy for war", "A classic problem in computer science about reaching consensus in a decentralized system with potentially malicious actors", "A type of mathematical equation", "A database error"]', 'A classic problem in computer science about reaching consensus in a decentralized system with potentially malicious actors', 'Blockchain consensus mechanisms solve this problem to ensure network security.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000922', '50000000-0000-0000-0000-000000000058', 'expert', 'mcq', 'Explain "Proof of Authority" (PoA).', '["The boss rules", "A consensus mechanism where transactions and blocks are validated by approved accounts", "A type of voting", "A cloud security standard"]', 'A consensus mechanism where transactions and blocks are validated by approved accounts', 'PoA is often used in private or consortium blockchains.', 'active'),
('60000000-0000-0000-0000-000000000923', '50000000-0000-0000-0000-000000000058', 'expert', 'mcq', 'What is "Finality" in blockchain?', '["The end of the world", "The point at which a transaction is considered permanent and cannot be reversed", "Closing a wallet", "Sending a receipt"]', 'The point at which a transaction is considered permanent and cannot be reversed', 'Different consensus mechanisms achieve finality at different speeds.', 'active'),
('60000000-0000-0000-0000-000000000924', '50000000-0000-0000-0000-000000000058', 'expert', 'mcq', 'Explain "51% Attack".', '["Getting a majority vote", "When a single entity gains control of more than half of the network mining/staking power, allowing them to manipulate the chain", "A type of database error", "A network virus"]', 'When a single entity gains control of more than half of the network mining/staking power, allowing them to manipulate the chain', 'A 51% attack can allow for double spending and blocking transactions.', 'active'),
('60000000-0000-0000-0000-000000000925', '50000000-0000-0000-0000-000000000058', 'expert', 'mcq', 'What is "pBFT" (Practical Byzantine Fault Tolerance)?', '["A type of encryption", "A consensus algorithm that handles up to 1/3 of nodes being malicious", "A fast database", "A cloud provider"]', 'A consensus algorithm that handles up to 1/3 of nodes being malicious', 'pBFT is used in systems like Hyperledger Fabric.', 'active'),
('60000000-0000-0000-0000-000000000926', '50000000-0000-0000-0000-000000000058', 'expert', 'mcq', 'What is "Proof of Burn"?', '["Sets tokens on fire", "A mechanism where users "burn" (destroy) tokens to gain mining rights or new tokens", "A type of cooling system", "A network fault"]', 'A mechanism where users "burn" (destroy) tokens to gain mining rights or new tokens', 'Proof of Burn is a way to bootstrap a new network or distribute tokens.', 'active'),

-- Topic 59: Ethereum & EVM (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000927', '50000000-0000-0000-0000-000000000059', 'simple', 'mcq', 'What is Ethereum?', '["A cryptocurrency only", "A decentralized, open-source blockchain with smart contract functionality", "A type of database", "A social network"]', 'A decentralized, open-source blockchain with smart contract functionality', 'Ethereum allows developers to build decentralized applications (dApps).', 'active'),
('60000000-0000-0000-0000-000000000928', '50000000-0000-0000-0000-000000000059', 'simple', 'mcq', 'What does "EVM" stand for?', '["Electronic Value Machine", "Ethereum Virtual Machine", "Extended Virtual Memory", "Ether Validate Monitor"]', 'Ethereum Virtual Machine', 'The EVM is the runtime environment for smart contracts in Ethereum.', 'active'),
('60000000-0000-0000-0000-000000000929', '50000000-0000-0000-0000-000000000059', 'simple', 'mcq', 'What is "Ether" (ETH)?', '["A type of chemical", "The native cryptocurrency of the Ethereum platform", "A type of cloud", "A network tool"]', 'The native cryptocurrency of the Ethereum platform', 'ETH is used to pay for transaction fees and computational services on the network.', 'active'),
('60000000-0000-0000-0000-000000000930', '50000000-0000-0000-0000-000000000059', 'simple', 'mcq', 'What is "Gas" in Ethereum?', '["Fuel for a car", "A unit that measures the amount of computational effort required to execute operations on the network", "A type of database", "A network signal"]', 'A unit that measures the amount of computational effort required to execute operations on the network', 'Gas fees are paid in ETH to compensate miners or validators.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000931', '50000000-0000-0000-0000-000000000059', 'intermediate', 'mcq', 'What is a "Smart Contract"?', '["A legal document on a tablet", "Self-executing contracts with the terms of the agreement directly written into lines of code", "A fast computer", "A type of AI"]', 'Self-executing contracts with the terms of the agreement directly written into lines of code', 'Smart contracts run on the blockchain and are tamper-proof.', 'active'),
('60000000-0000-0000-0000-000000000932', '50000000-0000-0000-0000-000000000059', 'intermediate', 'mcq', 'What is "ERC-20"?', '["A type of crypto exchange", "The technical standard used for all smart contracts on the Ethereum blockchain for fungible tokens", "A security standard", "A network protocol"]', 'The technical standard used for all smart contracts on the Ethereum blockchain for fungible tokens', 'ERC-20 tokens are compatible with each other and can be exchanged easily.', 'active'),
('60000000-0000-0000-0000-000000000933', '50000000-0000-0000-0000-000000000059', 'intermediate', 'mcq', 'What was "The Merge" in Ethereum?', '["Combining two coins", "Ethereum''s transition from Proof of Work to Proof of Stake", "Deleting old blocks", "Merging two accounts"]', 'Ethereum''s transition from Proof of Work to Proof of Stake', 'The Merge significantly reduced Ethereum''s energy consumption.', 'active'),
('60000000-0000-0000-0000-000000000934', '50000000-0000-0000-0000-000000000059', 'intermediate', 'mcq', 'What is a "Gwei"?', '["A type of food", "A denomination of Ether used to measure gas prices (1 Gwei = 10^-9 ETH)", "A login password", "A network router"]', 'A denomination of Ether used to measure gas prices (1 Gwei = 10^-9 ETH)', 'Transaction costs are often quoted in Gwei.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000935', '50000000-0000-0000-0000-000000000059', 'expert', 'mcq', 'What is "Account Abstraction" (ERC-4337)?', '["Deleting accounts", "Allowing users to use smart contract wallets as their primary accounts, enabling features like social recovery", "A type of encryption", "A database index"]', 'Allowing users to use smart contract wallets as their primary accounts, enabling features like social recovery', 'Account abstraction aims to improve Web3 user experience.', 'active'),
('60000000-0000-0000-0000-000000000936', '50000000-0000-0000-0000-000000000059', 'expert', 'mcq', 'Explain "Layer 2" scaling solutions (e.g., Optimism, Arbitrum).', '["A new blockchain", "Secondary frameworks or protocols built on top of an existing blockchain (Layer 1) to improve scalability and speed", "A faster database", "A cloud provider"]', 'Secondary frameworks or protocols built on top of an existing blockchain (Layer 1) to improve scalability and speed', 'Layer 2 solutions batch transactions before settling them on the main chain.', 'active'),
('60000000-0000-0000-0000-000000000937', '50000000-0000-0000-0000-000000000059', 'expert', 'mcq', 'What is "EIP-1559"?', '["A security code", "An upgrade that introduced a base fee and a tip mechanism for transaction pricing, with the base fee being burned", "A type of wallet", "A network fork"]', 'An upgrade that introduced a base fee and a tip mechanism for transaction pricing, with the base fee being burned', 'EIP-1559 made Ethereum transaction fees more predictable and introduced deflationary pressure.', 'active'),
('60000000-0000-0000-0000-000000000938', '50000000-0000-0000-0000-000000000059', 'expert', 'mcq', 'Explain "Zero-Knowledge Rollups" (ZK-Rollups).', '["Knowing nothing", "A Layer 2 scaling solution that uses zero-knowledge proofs to bundle and verify transactions off-chain", "A type of database", "A cloud region"]', 'A Layer 2 scaling solution that uses zero-knowledge proofs to bundle and verify transactions off-chain', 'ZK-rollups provide high security and scalability.', 'active'),
('60000000-0000-0000-0000-000000000939', '50000000-0000-0000-0000-000000000059', 'expert', 'mcq', 'What is "Staking" in Ethereum PoS?', '["Waiting for a bus", "The process of locking up ETH to participate in network security and earn rewards", "Selling coins", "A type of bug"]', 'The process of locking up ETH to participate in network security and earn rewards', 'Stakers run validator nodes and are responsible for proposing and attesting to new blocks.', 'active');

-- Topic 60: Solidity Programming (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000940', '50000000-0000-0000-0000-000000000060', 'simple', 'mcq', 'What is "Solidity"?', '["A type of rock", "An object-oriented, high-level language for implementing smart contracts", "A UI framework", "A database engine"]', 'An object-oriented, high-level language for implementing smart contracts', 'Solidity is the primary language used for writing smart contracts on Ethereum.', 'active'),
('60000000-0000-0000-0000-000000000941', '50000000-0000-0000-0000-000000000060', 'simple', 'mcq', 'Which keyword is used to declare a contract in Solidity?', '["class", "contract", "struct", "module"]', 'contract', 'A contract in Solidity is similar to a class in other languages.', 'active'),
('60000000-0000-0000-0000-000000000942', '50000000-0000-0000-0000-000000000060', 'simple', 'mcq', 'What is an "Address" type in Solidity?', '["A physical home address", "A 20-byte value representing an Ethereum wallet or contract account", "A string of text", "A type of number"]', 'A 20-byte value representing an Ethereum wallet or contract account', 'The address type is a fundamental data type in Solidity.', 'active'),
('60000000-0000-0000-0000-000000000943', '50000000-0000-0000-0000-000000000060', 'simple', 'mcq', 'What is the purpose of "msg.sender"?', '["The person receiving money", "The address of the account that called the current function", "A type of log", "A network router"]', 'The address of the account that called the current function', 'msg.sender is a global variable used for authentication and authorization.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000944', '50000000-0000-0000-0000-000000000060', 'intermediate', 'mcq', 'What is a "Modifier" in Solidity?', '["A person who changes code", "A reusable piece of code that can change the behavior of functions, often used for access control", "A type of variable", "A UI component"]', 'A reusable piece of code that can change the behavior of functions, often used for access control', 'Modifiers are often used to ensure only the contract owner can call certain functions.', 'active'),
('60000000-0000-0000-0000-000000000945', '50000000-0000-0000-0000-000000000060', 'intermediate', 'mcq', 'Explain "Mapping" in Solidity.', '["Drawing a map", "A key-value store data structure similar to a dictionary or hash table", "A list of numbers", "A type of event"]', 'A key-value store data structure similar to a dictionary or hash table', 'Mappings are commonly used to store balances and associations.', 'active'),
('60000000-0000-0000-0000-000000000946', '50000000-0000-0000-0000-000000000060', 'intermediate', 'mcq', 'What is the "payable" keyword used for?', '["To pay a bill", "To allow a function or address to receive Ether", "To encrypt a transaction", "To delete a contract"]', 'To allow a function or address to receive Ether', 'Functions without the payable keyword will reject incoming ETH.', 'active'),
('60000000-0000-0000-0000-000000000947', '50000000-0000-0000-0000-000000000060', 'intermediate', 'mcq', 'What are "Events" used for in Solidity?', '["A party", "To log data to the blockchain in a way that is easily searchable by off-chain applications", "A type of error", "A network signal"]', 'To log data to the blockchain in a way that is easily searchable by off-chain applications', 'Frontend applications listen for events to update their state.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000948', '50000000-0000-0000-0000-000000000060', 'expert', 'mcq', 'What is "Reentrancy" attack?', '["Going back into a room", "An exploit where a function is called repeatedly before the first invocation is finished, often used to drain funds", "A type of database error", "A network virus"]', 'An exploit where a function is called repeatedly before the first invocation is finished, often used to drain funds', 'Reentrancy is a classic smart contract vulnerability.', 'active'),
('60000000-0000-0000-0000-000000000949', '50000000-0000-0000-0000-000000000060', 'expert', 'mcq', 'Explain "Gas Limit" vs "Gas Price".', '["Limits on a stove", "Gas Limit is the maximum gas a user is willing to spend for a transaction; Gas Price is the amount per unit of gas", "They are identical", "One is for ETH, one for BTC"]', 'Gas Limit is the maximum gas a user is willing to spend for a transaction; Gas Price is the amount per unit of gas', 'Transaction Fee = Gas Used * Gas Price.', 'active');

-- Topic 61: Liquidity & Exchanges (DEX) (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000950', '50000000-0000-0000-0000-000000000061', 'simple', 'mcq', 'What is a "DEX" (Decentralized Exchange)?', '["A bank", "A peer-to-peer marketplace where transactions occur directly between crypto traders without a middleman", "A type of database", "A social network"]', 'A peer-to-peer marketplace where transactions occur directly between crypto traders without a middleman', 'DEXs use smart contracts to facilitate trading.', 'active'),
('60000000-0000-0000-0000-000000000951', '50000000-0000-0000-0000-000000000061', 'simple', 'mcq', 'Which platform is a popular DEX on Ethereum?', '["Binance", "Coinbase", "Uniswap", "Kraken"]', 'Uniswap', 'Uniswap pioneered the automated market maker (AMM) model.', 'active'),
('60000000-0000-0000-0000-000000000952', '50000000-0000-0000-0000-000000000061', 'simple', 'mcq', 'What is a "Liquidity Pool"?', '["A swimming pool", "A collection of funds locked in a smart contract that provide liquidity for a DEX", "A group of hackers", "A network of cloud servers"]', 'A collection of funds locked in a smart contract that provide liquidity for a DEX', 'Liquidity pools are used by AMMs to facilitate trading.', 'active'),
('60000000-0000-0000-0000-000000000953', '50000000-0000-0000-0000-000000000061', 'simple', 'mcq', 'Who are "Liquidity Providers" (LPs)?', '["Bankers", "Users who provide assets to a liquidity pool in exchange for fees", "A type of bot", "Cloud providers"]', 'Users who provide assets to a liquidity pool in exchange for fees', 'LPs earn a portion of the trading fees as a reward.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000954', '50000000-0000-0000-0000-000000000061', 'intermediate', 'mcq', 'What is an "AMM" (Automated Market Maker)?', '["A type of robot", "A type of DEX protocol that relies on a mathematical formula to price assets", "A central bank", "A network router"]', 'A type of DEX protocol that relies on a mathematical formula to price assets', 'AMMs allow assets to be traded automatically by using liquidity pools.', 'active'),
('60000000-0000-0000-0000-000000000955', '50000000-0000-0000-0000-000000000061', 'intermediate', 'mcq', 'What is "Impermanent Loss"?', '["Losing your wallet", "The temporary loss of funds experienced by liquidity providers due to volatility in a trading pair", "A type of math error", "A network timeout"]', 'The temporary loss of funds experienced by liquidity providers due to volatility in a trading pair', 'Impermanent loss occurs when the relative price of the pooled assets changes.', 'active'),
('60000000-0000-0000-0000-000000000956', '50000000-0000-0000-0000-000000000061', 'intermediate', 'mcq', 'What is "Slippage" in trading?', '["Falling on ice", "The difference between the expected price of a trade and the price at which the trade is executed", "A type of crypto fee", "A network lag"]', 'The difference between the expected price of a trade and the price at which the trade is executed', 'Slippage is more common in markets with low liquidity.', 'active'),
('60000000-0000-0000-0000-000000000957', '50000000-0000-0000-0000-000000000061', 'intermediate', 'mcq', 'What is "Yield Farming"?', '["Planting crops", "The practice of staking or lending crypto assets to generate high returns or rewards in the form of additional cryptocurrency", "Buying a farm with BTC", "A type of mining hardware"]', 'The practice of staking or lending crypto assets to generate high returns or rewards in the form of additional cryptocurrency', 'Yield farming involves moving assets across different DeFi protocols to maximize profit.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000958', '50000000-0000-0000-0000-000000000061', 'expert', 'mcq', 'Explain "Flash Loans".', '["Very fast loans", "A type of uncollateralized loan where the funds must be borrowed and repaid within the same blockchain transaction", "A payday loan", "A type of credit card"]', 'A type of uncollateralized loan where the funds must be borrowed and repaid within the same blockchain transaction', 'Flash loans are used for arbitrage and liquidations but can also be used in exploits.', 'active'),
('60000000-0000-0000-0000-000000000959', '50000000-0000-0000-0000-000000000061', 'expert', 'mcq', 'What is "MEV" (Maximal Extractable Value)?', '["The total supply of coins", "The maximum value that can be extracted from block production over and above the standard block reward and gas fees", "A type of exchange", "A network protocol"]', 'The maximum value that can be extracted from block production over and above the standard block reward and gas fees', 'MEV often involves frontrunning or sandwiching user transactions.', 'active'),
('60000000-0000-0000-0000-000000000960', '50000000-0000-0000-0000-000000000061', 'expert', 'mcq', 'Explain "Governance Tokens".', '["Tokens used for paying rent", "Tokens that grant their holders the right to vote on changes to a DeFi protocol", "A type of stablecoin", "A security standard"]', 'Tokens that grant their holders the right to vote on changes to a DeFi protocol', 'Governance tokens are a key part of Decentralized Autonomous Organizations (DAOs).', 'active'),
('60000000-0000-0000-0000-000000000961', '50000000-0000-0000-0000-000000000061', 'expert', 'mcq', 'What is "Total Value Locked" (TVL)?', '["The money in a bank vault", "A metric that represents the total amount of assets that are currently being staked or lent within a DeFi protocol", "A security feature", "The price of ETH"]', 'A metric that represents the total amount of assets that are currently being staked or lent within a DeFi protocol', 'TVL is used to measure the adoption and liquidity of a DeFi platform.', 'active'),
('60000000-0000-0000-0000-000000000962', '50000000-0000-0000-0000-000000000061', 'expert', 'mcq', 'What are "Aggregators" in DeFi?', '["Groups of people", "Platforms that source liquidity from multiple DEXs to provide users with the best possible trade prices", "A type of miner", "A cloud provider"]', 'Platforms that source liquidity from multiple DEXs to provide users with the best possible trade prices', 'Examples include 1inch and Paraswap.', 'active');

-- Topic 62: Stablecoins & Oracles (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000963', '50000000-0000-0000-0000-000000000062', 'simple', 'mcq', 'What is a "Stablecoin"?', '["A coin that never moves", "A cryptocurrency designed to maintain a stable value relative to an asset like the US dollar", "A type of database", "A network rule"]', 'A cryptocurrency designed to maintain a stable value relative to an asset like the US dollar', 'Stablecoins provide a refuge from the volatility of most cryptocurrencies.', 'active'),
('60000000-0000-0000-0000-000000000964', '50000000-0000-0000-0000-000000000062', 'simple', 'mcq', 'Which of these is a popular stablecoin?', '["Bitcoin", "Ethereum", "USDC", "Dogecoin"]', 'USDC', 'USD Coin (USDC) is a fully reserved stablecoin pegged to the US dollar.', 'active'),
('60000000-0000-0000-0000-000000000965', '50000000-0000-0000-0000-000000000062', 'simple', 'mcq', 'What is an "Oracle" in blockchain?', '["A crystal ball", "A service that provides external data to smart contracts on a blockchain", "A type of database", "A cloud region"]', 'A service that provides external data to smart contracts on a blockchain', 'Oracles bridge the gap between blockchains and the real world.', 'active'),
('60000000-0000-0000-0000-000000000966', '50000000-0000-0000-0000-000000000062', 'simple', 'mcq', 'Which project is a leading decentralized oracle network?', '["Uniswap", "Chainlink", "OpenSea", "Solana"]', 'Chainlink', 'Chainlink provides reliable, tamper-proof data feeds for smart contracts.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000967', '50000000-0000-0000-0000-000000000062', 'intermediate', 'mcq', 'What is a "Fiat-collateralized Stablecoin"?', '["Backed by gold", "Backed by traditional currencies like the US dollar held in a bank account", "Backed by other cryptos", "No backing"]', 'Backed by traditional currencies like the US dollar held in a bank account', 'Examples include USDT and USDC.', 'active'),
('60000000-0000-0000-0000-000000000968', '50000000-0000-0000-0000-000000000062', 'intermediate', 'mcq', 'What is a "Crypto-collateralized Stablecoin"?', '["Backed by dollars", "Backed by other cryptocurrencies as collateral", "Backed by silver", "A type of NFT"]', 'Backed by other cryptocurrencies as collateral', 'DAI is a prominent example of a crypto-collateralized stablecoin.', 'active'),
('60000000-0000-0000-0000-000000000969', '50000000-0000-0000-0000-000000000062', 'intermediate', 'mcq', 'What is the "Oracle Problem"?', '["The oracle is slow", "The challenge of getting reliable, off-chain data into a trustless, on-chain environment", "Oracles are too expensive", "A database error"]', 'The challenge of getting reliable, off-chain data into a trustless, on-chain environment', 'If the oracle is compromised, the smart contract relying on its data can be exploited.', 'active'),
('60000000-0000-0000-0000-000000000970', '50000000-0000-0000-0000-000000000062', 'intermediate', 'mcq', 'What is an "Algorithmic Stablecoin"?', '["A coin for math", "A stablecoin that uses algorithms and smart contracts to manage its supply and maintain a peg", "A backed coin", "A network rule"]', 'A stablecoin that uses algorithms and smart contracts to manage its supply and maintain a peg', 'Algorithmic stablecoins (like the failed TerraUSD) do not necessarily have 1:1 asset backing.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000971', '50000000-0000-0000-0000-000000000062', 'expert', 'mcq', 'Explain "Proof of Reserves" (PoR).', '["Counting coins in a piggy bank", "An independent audit or cryptographic proof that an exchange or stablecoin issuer actually holds the assets they claim to have", "A type of consensus", "A security standard"]', 'An independent audit or cryptographic proof that an exchange or stablecoin issuer actually holds the assets they claim to have', 'PoR improves transparency and trust in centralized crypto entities.', 'active'),
('60000000-0000-0000-0000-000000000972', '50000000-0000-0000-0000-000000000062', 'expert', 'mcq', 'What is "Decentralized Oracle Network" (DON)?', '["A group of crystal balls", "A network of independent oracle nodes that aggregate data to provide a more reliable and secure feed", "A fast database", "A cloud provider"]', 'A network of independent oracle nodes that aggregate data to provide a more reliable and secure feed', 'DONs mitigate the risk of a single point of failure in data delivery.', 'active'),
('60000000-0000-0000-0000-000000000973', '50000000-0000-0000-0000-000000000062', 'expert', 'mcq', 'Explain "Rebasing" in algorithmic stablecoins.', '["Changing the price", "An algorithm that adjusts the total supply of a token in users'' wallets based on price fluctuations", "A type of fork", "A security code"]', 'An algorithm that adjusts the total supply of a token in users'' wallets based on price fluctuations', 'Rebasing aims to bring the price back to the target peg by changing the circulating supply.', 'active'),
('60000000-0000-0000-0000-000000000974', '50000000-0000-0000-0000-000000000062', 'expert', 'mcq', 'What is "Collateralization Ratio"?', '["The height of a building", "The ratio of the value of the collateral to the value of the issued stablecoins or debt", "A type of fee", "A network routing protocol"]', 'The ratio of the value of the collateral to the value of the issued stablecoins or debt', 'Over-collateralization is common in crypto-backed systems like MakerDAO.', 'active'),
('60000000-0000-0000-0000-000000000975', '50000000-0000-0000-0000-000000000062', 'expert', 'mcq', 'How do "Oracles" prevent data manipulation?', '["By guessing", "Using multiple data sources, node reputation, and staking mechanisms to ensure data accuracy", "By encrypting everything", "A type of firewall"]', 'Using multiple data sources, node reputation, and staking mechanisms to ensure data accuracy', 'Secure oracles are vital for the integrity of DeFi and other smart contract applications.', 'active');

-- Topic 63: NFT Standards & Markets (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000976', '50000000-0000-0000-0000-000000000063', 'simple', 'mcq', 'What does "NFT" stand for?', '["National Food Ticket", "Non-Fungible Token", "New Financial Technology", "Network File Transfer"]', 'Non-Fungible Token', 'NFTs are unique digital assets representing ownership of items like art, collectibles, or music.', 'active'),
('60000000-0000-0000-0000-000000000977', '50000000-0000-0000-0000-000000000063', 'simple', 'mcq', 'What does "Non-Fungible" mean?', '["Tasty", "Unique and non-interchangeable", "Easy to copy", "Disposable"]', 'Unique and non-interchangeable', 'Unlike Bitcoin or physical money, one NFT cannot be replaced by another identical one.', 'active'),
('60000000-0000-0000-0000-000000000978', '50000000-0000-0000-0000-000000000063', 'simple', 'mcq', 'Which Ethereum standard is most commonly used for NFTs?', '["ERC-20", "ERC-721", "ERC-1155", "ERC-777"]', 'ERC-721', 'ERC-721 is the pioneer standard for unique non-fungible tokens.', 'active'),
('60000000-0000-0000-0000-000000000979', '50000000-0000-0000-0000-000000000063', 'simple', 'mcq', 'Where are NFTs primarily bought and sold?', '["Stock exchange", "NFT marketplaces like OpenSea or Blur", "A physical grocery store", "A bank"]', 'NFT marketplaces like OpenSea or Blur', 'Marketplaces allow users to list, discover, and trade NFTs.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000980', '50000000-0000-0000-0000-000000000063', 'intermediate', 'mcq', 'What is "NFT Metadata"?', '["The price of the NFT", "Data that provides information about the NFT, such as its name, description, and link to the media it represents", "The owner''s login", "A type of encryption"]', 'Data that provides information about the NFT, such as its name, description, and link to the media it represents', 'Metadata is often stored off-chain on systems like IPFS.', 'active'),
('60000000-0000-0000-0000-000000000981', '50000000-0000-0000-0000-000000000063', 'intermediate', 'mcq', 'What is "ERC-1155"?', '["A type of wallet", "A multi-token standard that allows a single contract to represent both fungible and non-fungible tokens", "A protocol for video", "A security standard"]', 'A multi-token standard that allows a single contract to represent both fungible and non-fungible tokens', 'ERC-1155 is more efficient for games where items can be unique or semi-fungible.', 'active'),
('60000000-0000-0000-0000-000000000982', '50000000-0000-0000-0000-000000000063', 'intermediate', 'mcq', 'What is "Minting" an NFT?', '["Eating a candy", "The process of publishing a unique instance of a token on the blockchain", "Selling an NFT", "Buying an NFT"]', 'The process of publishing a unique instance of a token on the blockchain', 'Minting makes the digital asset part of the blockchain immutable record.', 'active'),
('60000000-0000-0000-0000-000000000983', '50000000-0000-0000-0000-000000000063', 'intermediate', 'mcq', 'What is the role of "IPFS" in the NFT ecosystem?', '["A type of CPU", "InterPlanetary File System, used for decentralized storage of large NFT media and metadata files", "A network router", "A programming language"]', 'InterPlanetary File System, used for decentralized storage of large NFT media and metadata files', 'IPFS prevents NFT data from being lost if a central server goes down.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000984', '50000000-0000-0000-0000-000000000063', 'expert', 'mcq', 'Explain "Fractionalized NFTs".', '["Breaking an NFT", "A process where an NFT is divided into smaller "fractions" (fungible tokens), allowing multiple people to own a piece of it", "A type of math", "A network fault"]', 'A process where an NFT is divided into smaller "fractions" (fungible tokens), allowing multiple people to own a piece of it', 'Fractionalization increases liquidity for high-value NFTs.', 'active'),
('60000000-0000-0000-0000-000000000985', '50000000-0000-0000-0000-000000000063', 'expert', 'mcq', 'What is a "Generative Art" NFT?', '["Art created by a human", "Art created using an algorithm or code to generate unique variations often at the time of minting", "A type of photo", "A database record"]', 'Art created using an algorithm or code to generate unique variations often at the time of minting', 'Projects like CryptoPunks and Art Blocks are famous examples.', 'active'),
('60000000-0000-0000-0000-000000000986', '50000000-0000-0000-0000-000000000063', 'expert', 'mcq', 'What are "NFT Royalties"?', '["King''s money", "A set percentage of every secondary sale that is automatically paid to the original creator", "A type of fee", "A network signal"]', 'A set percentage of every secondary sale that is automatically paid to the original creator', 'Royalties are often implemented via smart contracts or marketplace policies.', 'active'),
('60000000-0000-0000-0000-000000000987', '50000000-0000-0000-0000-000000000063', 'expert', 'mcq', 'What is a "Burn" function in NFT smart contracts?', '["A way to heat the server", "A function that allows an NFT to be permanently removed from circulation", "A type of error", "A cloud region"]', 'A function that allows an NFT to be permanently removed from circulation', 'Burning is often used to reduce supply or upgrade to a new version.', 'active'),
('60000000-0000-0000-0000-000000000988', '50000000-0000-0000-0000-000000000063', 'expert', 'mcq', 'What are "On-chain" vs "Off-chain" NFTs?', '["One is for chains, one for ropes", "On-chain NFTs store all data on the blockchain; Off-chain NFTs store media or metadata on external servers like IPFS or AWS", "Nonsense", "A type of UI design"]', 'On-chain NFTs store all data on the blockchain; Off-chain NFTs store media or metadata on external servers like IPFS or AWS', 'On-chain storage is more secure but much more expensive.', 'active');

-- Topic 64: Web3 Security & Audits (12 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000989', '50000000-0000-0000-0000-000000000064', 'simple', 'mcq', 'What is a "Smart Contract Audit"?', '["A type of bank account", "An extensive review of a smart contract''s code to find vulnerabilities and bugs before deployment", "A UI test", "A network speed test"]', 'An extensive review of a smart contract''s code to find vulnerabilities and bugs before deployment', 'Audits are essential for ensuring the security of DeFi and high-value projects.', 'active'),
('60000000-0000-0000-0000-000000000990', '50000000-0000-0000-0000-000000000064', 'simple', 'mcq', 'What is a "Private Key" in Web3?', '["A literal key", "A secret number used in cryptography that allows a user to sign transactions and access their funds", "A login password", "A network tool"]', 'A secret number used in cryptography that allows a user to sign transactions and access their funds', 'Losing your private key means losing access to your funds forever.', 'active'),
('60000000-0000-0000-0000-000000000991', '50000000-0000-0000-0000-000000000064', 'simple', 'mcq', 'What is "Phishing" in Web3?', '["Catching fish", "An attack where users are tricked into revealing their private keys or seed phrases", "A type of mining", "A network lag"]', 'An attack where users are tricked into revealing their private keys or seed phrases', 'Web3 phishing often uses fake wallet websites or misleading social media posts.', 'active'),
('60000000-0000-0000-0000-000000000992', '50000000-0000-0000-0000-000000000064', 'simple', 'mcq', 'What is a "Multisig" wallet?', '["A lot of signatures", "A wallet that requires multiple private keys to authorize a transaction", "A single user wallet", "A type of physical lock"]', 'A wallet that requires multiple private keys to authorize a transaction', 'Multisig wallets provide significantly higher security for organizations and groups.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000993', '50000000-0000-0000-0000-000000000064', 'intermediate', 'mcq', 'What is "Rug Pull" in crypto?', '["Cleaning the house", "A malicious maneuver in the cryptocurrency industry where crypto developers abandon a project and run away with investors'' funds", "A type of consensus", "A market pump"]', 'A malicious maneuver in the cryptocurrency industry where crypto developers abandon a project and run away with investors'' funds', 'Rug pulls often involve draining liquidity from a DEX.', 'active'),
('60000000-0000-0000-0000-000000000994', '50000000-0000-0000-0000-000000000064', 'intermediate', 'mcq', 'What is an "Oracle Attack"?', '["A fight with a crystal ball", "Manipulating the data feed of an oracle to exploit a smart contract", "A network timeout", "A type of math error"]', 'Manipulating the data feed of an oracle to exploit a smart contract', 'Oracle attacks are common in DeFi liquidations or price-based exploits.', 'active'),
('60000000-0000-0000-0000-000000000995', '50000000-0000-0000-0000-000000000064', 'intermediate', 'mcq', 'What is "Honeypot" contract?', '["A jar of honey", "A malicious smart contract that appears to have an obvious flaw that would allow a user to drain funds, but actually traps them", "A type of exchange", "A network router"]', 'A malicious smart contract that appears to have an obvious flaw that would allow a user to drain funds, but actually traps them', 'Honeypots predate on greedy or inexperienced attackers.', 'active'),
('60000000-0000-0000-0000-000000000996', '50000000-0000-0000-0000-000000000064', 'intermediate', 'mcq', 'What is "Formal Verification"?', '["Checking an ID", "Using mathematical proofs to ensure that a smart contract follows its intended logic and is free of certain bugs", "A type of UI test", "A login system"]', 'Using mathematical proofs to ensure that a smart contract follows its intended logic and is free of certain bugs', 'Formal verification provides a higher level of assurance than traditional testing.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000997', '50000000-0000-0000-0000-000000000064', 'expert', 'mcq', 'Explain "Front-running" in Web3.', '["Running in front", "The practice of placing a transaction in a queue with knowledge of a pending transaction to profit from the price movement", "A type of consensus", "A database index"]', 'The practice of placing a transaction in a queue with knowledge of a pending transaction to profit from the price movement', 'Attacker often pay higher gas fees to ensure their transaction is processed first.', 'active'),
('60000000-0000-0000-0000-000000000998', '50000000-0000-0000-0000-000000000064', 'expert', 'mcq', 'What is a "Proxy Contract" in Web3?', '["A temporary contract", "A contract that delegates all calls to another contract, often used to make smart contracts upgradeable", "A type of stablecoin", "A security standard"]', 'A contract that delegates all calls to another contract, often used to make smart contracts upgradeable', 'Proxies allow developers to fix bugs or add features to already deployed contracts.', 'active'),
('60000000-0000-0000-0000-000000000999', '50000000-0000-0000-0000-000000000064', 'expert', 'mcq', 'What is "Code is Law" philosophy?', '["Lawyers writing code", "The idea that the outcome of smart contracts should be final and immutable, even in cases of unintended bugs or exploits", "A type of legal system", "A programming style"]', 'The idea that the outcome of smart contracts should be final and immutable, even in cases of unintended bugs or exploits', 'This philosophy was famously tested during the DAO hack on Ethereum.', 'active'),
('60000000-0000-0000-0000-000000001000', '50000000-0000-0000-0000-000000000064', 'expert', 'mcq', 'Explain "Time-lock" in smart contracts.', '["A lock on a clock", "A mechanism that prevents certain actions from being taken until a specified period of time has passed", "A type of consensus", "A database error"]', 'A mechanism that prevents certain actions from being taken until a specified period of time has passed', 'Time-locks are often used for protocol upgrades to give users time to exit if they disagree.', 'active');
